import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  // Load texture from atlas
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  // Assume texture is already loaded (cached) and has .image dimensions
  const texW = texture.image.width;
  const texH = texture.image.height;

  // Atlas source rect from config (pixels)
  const { x: rectX, y: rectY, width: rectW, height: rectH } = config.atlasRegion?.sourceRect || { x: 0, y: 0, width: 512, height: 320 };

  // UV offset/repeat for the sub‑region (v-flipped because Three.js v=0 at bottom)
  const uOff = rectX / texW;
  const vOff = 1 - (rectY + rectH) / texH;
  const uScale = rectW / texW;
  const vScale = rectH / texH;
  texture.offset.set(uOff, vOff);
  texture.repeat.set(uScale, vScale);
  texture.needsUpdate = true;

  // Plane sized to match rect aspect ratio
  const aspect = rectW / rectH;
  const geometry = new THREE.PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true, // assume alpha channel present
    depthWrite: false,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  mesh.position.copy(config.position || new THREE.Vector3(0, 3, 0));
  mesh.rotation.setFromVector3(config.rotation || new THREE.Vector3(0, 0, 0));
  mesh.scale.copy(config.scale || new THREE.Vector3(1, 1, 1));

  // Manual billboarding – keep face toward camera
  const billboardHandler = (camera) => {
    mesh.lookAt(camera.position);
  };
  mesh.userData.handlers = {
    update: billboardHandler,
  };

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // No GSAP timelines in this node
  };

  return mesh;
}
